class SnapshotArray {
public:
    map<int,map<int,int>> snaps;
    int snap_i=0;
    SnapshotArray(int length) {
        for(int i=0;i<length;i++)
        {
            map<int,int> mp;
            mp[0]=0;
            snaps[i]=mp;
        }
    }

    void set(int index, int val) {
        snaps[index][snap_i]=val;
    }

    int snap() {
        snap_i+=1;
        return snap_i-1;
    }

    int get(int index, int snap_id) {
        auto it=snaps[index].upper_bound(snap_id);
        it--;
        return it->second;
    }
};

